    return ["docker", "run", "--rm", "--name", name, "--label", "campaign=c1", "--gpus", "all",
            "-v", f"{model[0]}:/m:ro", "-v", f"{TIN}:/tin:ro", *extra_mounts, "--entrypoint", entry, ENG[engine]]


def completion(exp, arm, engine, model, args, prompt, n=128, rnd=0, extra=None):
