    for rnd in (1, 2):
        for arm, model, a in [("reap-K0", REAP, ["-ngl", "99"]), ("reap-K12", REAP, ["-ngl", "99", "--n-cpu-moe", "12"]),
                              ("full-K30", QWEN, ["-ngl", "99", "--n-cpu-moe", "30"])][:: 1 if rnd == 1 else -1]:
            for prompt in ("chat.txt", "code.txt"):
                completion("e3", arm, "rel1", model, a, prompt, rnd=rnd)


