                (f"K{K}-mtp2", ["-ngl", "99", "--n-cpu-moe", str(K), "--spec-type", "draft-mtp", "--spec-draft-n-max", "2"]),
                (f"K{K}-mtp3", ["-ngl", "99", "--n-cpu-moe", str(K), "--spec-type", "draft-mtp", "--spec-draft-n-max", "3"])]
        for rnd in (1, 2):
