BASE_MIB = 1800  # all-CPU-experts footprint measured in D039 (K=48: 1798 MiB)


def phase_aa():
    pids = curl_pids()
    for i in range(3):
        completion("aa", "with_dl", "rel1", QWEN, ["-ngl", "99", "--n-cpu-moe", "30"], "chat.txt", rnd=i)
    for p in pids: os.kill(p, signal.SIGSTOP)
