def e1_arms(B, cache_mib):
    arms = [("S1", "rel1", ["-ngl", "99", "--n-cpu-moe", str(K_B[B])]),
            ("C1", "rel1", ["-ngl", "99", "--n-cpu-moe", "48", "--moe-cache-mib", str(cache_mib)])]
